function Driver:Step(operations, milliseconds)
    if self.result then return self:GetResult() end
    operations,milliseconds=operations or 64,milliseconds or self.budgets.sliceMs
    if not Integer(operations,1) or operations>4096 or not Finite(milliseconds) or milliseconds<=0 then return nil,"invalid_step_budget" end
    milliseconds=math.min(milliseconds,self.budgets.sliceMs)
    local started=Sample(self.clock)
    if self.result then return self:GetResult() end
    if not started or started<self.last then
        Stop(self,"unknown","benchmark_v2_clock_invalid",true);return self:GetResult()
    end
    if started-self.started>=self.budgets.elapsedMs or self.cpuMs>=self.budgets.cpuMs then
        Stop(self,"budget_exceeded","benchmark_v2_budget",true);return self:GetResult()
    end
    self.driverTicks=(self.driverTicks or 0)+1
    if self.phase=="search" then self:SearchStep(operations,milliseconds)
    else
        if self.phase=="load" then self:LoadStep(milliseconds<self.budgets.sliceMs and 1 or operations)
        elseif self.phase=="new" then self:OpenPlanner()
        else
            for _=1,operations do
                if self.phase=="catalog" then self:CatalogUnit() else self:BindUnit() end
                if self.result or self.phase=="load" or self.phase=="new" then break end
                local now=Sample(self.clock)
                if self.result then break end
                if not now or now<started then Stop(self,"unknown","benchmark_v2_clock_invalid",true);break end
                if now-started>=milliseconds then break end
            end
        end
    end
    local stopped=Sample(self.clock)
    if self.result and self.result.status=="cancelled" then return self:GetResult() end
    if not stopped or stopped<started then
        Stop(self,"unknown","benchmark_v2_clock_invalid",true,true);return self:GetResult()
    end
    self.cpuMs,self.last=self.cpuMs+stopped-started,stopped
    if (not self.result or self.result.status~="cancelled")
        and (self.cpuMs>=self.budgets.cpuMs or stopped-self.started>=self.budgets.elapsedMs) then
        Stop(self,"budget_exceeded","benchmark_v2_budget",true,true);return self:GetResult()
    end
    return self:GetResult()
end--[[APR_DIAG]]; Driver.Step = APRTrace("APR-Core/features/navigation/NavigationBenchmarkV2.lua:345:Driver:Step#26", Driver.Step)--[[/APR_DIAG]]

